use vstd::prelude::*;

verus! {

    /// For an input vector `x` of length `n`, we produce a weight‐vector
    /// of the same length such that
    ///   - weight[0]     == 0.5
    ///   - weight[n − 1] == 0.5
    ///   - all other weight[i] == 1.0
    fn chebweight(x: Vec<f32>) -> (weights: Vec<f32>)
        ensures
            // output has the same length as input
            weights.len() == x.len(),
            // and for every index i, we have the two‐case property:
            forall |i: usize| i < x.len() ==>
                if i == 0 || i + 1 == x.len() {
                    weights[i] == 0.5f32
                } else {
                    weights[i] == 1.0f32
                },
    {
        let n = x.len();
        let mut weights = Vec::with_capacity(n);
        let mut i: usize = 0;
        // We iterate i = 0 .. n and maintain:
        //   * i ≤ n
        //   * weights.len() == i
        //   * for all j < i, weights[j] satisfies the two‐case property
        while i < n
            invariant
                i <= n,
                weights.len() == i,
                forall |j: usize| j < i ==>
                    if j == 0 || j + 1 == n {
                        weights[j] == 0.5f32
                    } else {
                        weights[j] == 1.0f32
                    },
            decreases n - i,
        {
            let w = if i == 0 || i + 1 == n {
                0.5f32
            } else {
                1.0f32
            };
            weights.push(w);
            i += 1;
        }
        weights
    }
}

